mapper.select:
SELECT * FROM settlement_exception


        AND exception_type = #{exceptionType}


        AND exception_level = #{exceptionLevel}


        AND resolution_status = #{resolutionStatus}


        AND DATE(create_time) >= #{startDate}


        AND DATE(create_time) <= #{endDate}


        AND org_id = #{orgId}


ORDER BY 
    CASE exception_level 
        WHEN 'CRITICAL' THEN 1 
        WHEN 'HIGH' THEN 2 
        WHEN 'MEDIUM' THEN 3 
        ELSE 4 
    END,
    create_time DESC

SELECT * FROM settlement_exception
WHERE pending_id = #{pendingId}
ORDER BY create_time DESC

SELECT * FROM settlement_exception
WHERE record_id = #{recordId}
ORDER BY create_time DESC

SELECT COUNT(*) as totalCount, SUM(CASE WHEN resolution_status = 'OPEN' THEN 1 ELSE 0 END) as openCount, SUM(CASE WHEN resolution_status = 'ASSIGNED' THEN 1 ELSE 0 END) as assignedCount, SUM(CASE WHEN resolution_status = 'IN_PROGRESS' THEN 1 ELSE 0 END) as inProgressCount, SUM(CASE WHEN resolution_status = 'RESOLVED' THEN 1 ELSE 0 END) as resolvedCount, SUM(CASE WHEN resolution_status = 'CLOSED' THEN 1 ELSE 0 END) as closedCount, SUM(CASE WHEN exception_level = 'CRITICAL' THEN 1 ELSE 0 END) as criticalCount, SUM(CASE WHEN exception_level = 'HIGH' THEN 1 ELSE 0 END) as highCount, SUM(CASE WHEN exception_level = 'MEDIUM' THEN 1 ELSE 0 END) as mediumCount, SUM(CASE WHEN exception_level = 'LOW' THEN 1 ELSE 0 END) as lowCount FROM settlement_exception WHERE org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}

SELECT exception_type, COUNT(*) as count, SUM(CASE WHEN resolution_status IN ('OPEN', 'ASSIGNED', 'IN_PROGRESS', 'ESCALATED') THEN 1 ELSE 0 END) as unresolvedCount, AVG(CASE WHEN resolution_time IS NOT NULL THEN TIMESTAMPDIFF(HOUR, create_time, resolution_time) ELSE NULL END) as avgResolutionHours FROM settlement_exception WHERE org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY exception_type ORDER BY count DESC

SELECT exception_level, COUNT(*) as count, SUM(CASE WHEN resolution_status IN ('OPEN', 'ASSIGNED', 'IN_PROGRESS', 'ESCALATED') THEN 1 ELSE 0 END) as unresolvedCount, AVG(CASE WHEN resolution_time IS NOT NULL THEN TIMESTAMPDIFF(HOUR, create_time, resolution_time) ELSE NULL END) as avgResolutionHours FROM settlement_exception WHERE org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY exception_level ORDER BY CASE exception_level WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 ELSE 4 END

SELECT error_code, error_message, COUNT(*) as count, MAX(create_time) as lastOccurrence, SUM(CASE WHEN resolution_status IN ('OPEN', 'ASSIGNED', 'IN_PROGRESS', 'ESCALATED') THEN 1 ELSE 0 END) as unresolvedCount FROM settlement_exception WHERE org_id = #{orgId} AND error_code IS NOT NULL
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY error_code, error_message ORDER BY count DESC

SELECT exception_type, exception_level, COUNT(*) as resolvedCount, AVG(TIMESTAMPDIFF(HOUR, create_time, resolution_time)) as avgResolutionHours, MIN(TIMESTAMPDIFF(HOUR, create_time, resolution_time)) as minResolutionHours, MAX(TIMESTAMPDIFF(HOUR, create_time, resolution_time)) as maxResolutionHours FROM settlement_exception WHERE org_id = #{orgId} AND resolution_status = 'RESOLVED' AND resolution_time IS NOT NULL
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY exception_type, exception_level ORDER BY avgResolutionHours DESC

SELECT assigned_user, COUNT(*) as assignedCount, SUM(CASE WHEN resolution_status = 'RESOLVED' THEN 1 ELSE 0 END) as resolvedCount, SUM(CASE WHEN resolution_status IN ('ASSIGNED', 'IN_PROGRESS') THEN 1 ELSE 0 END) as activeCount, AVG(CASE WHEN resolution_time IS NOT NULL THEN TIMESTAMPDIFF(HOUR, assigned_time, resolution_time) ELSE NULL END) as avgHandlingHours FROM settlement_exception WHERE org_id = #{orgId} AND assigned_user IS NOT NULL
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY assigned_user ORDER BY assignedCount DESC

SELECT error_code, error_message, exception_type, COUNT(*) as occurrenceCount, MIN(create_time) as firstOccurrence, MAX(create_time) as lastOccurrence, DATEDIFF(MAX(create_time), MIN(create_time)) as daySpan FROM settlement_exception WHERE org_id = #{orgId} AND error_code IS NOT NULL
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY error_code, error_message, exception_type HAVING COUNT(*) >= #{minOccurrences} ORDER BY occurrenceCount DESC, daySpan DESC
